package ama.transcript;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import ama.contract.TranscriptContracts;import ama.contract.MinutesContracts;
class MinutesGenerationPrerequisiteTest {
 final String id="00000000-0000-4000-8000-000000000001";
 Map<String,Object> root(){var r=new HashMap<String,Object>();r.put("revision",7L);r.put("ever_published",0L);r.put("lifecycle","ACTIVE");r.put("governance_state","ACTIVE");r.put("stage","MINUTES_PENDING");r.put("transcript_confirmation_id",id);r.put("template_revision_id",null);r.put("exclusion_revision_id",null);r.put("material_snapshot_id",null);r.put("final_confirmation_id",null);r.put("materials_pending",0L);return r;}
 @Test void confirmedTranscriptWithoutInitialSettingsHasASpecificRecoverablePrerequisite(){var f=assertThrows(TranscriptContracts.Failure.class,()->JdbcMinutesGenerationPreparation.writable(root(),7));assertEquals(422,f.status());assertEquals("SETTINGS_REQUIRED",f.code());}
 @Test void aMissingTranscriptConfirmationRequiresConfirmationInsteadOfAnUnavailableService(){var r=root();r.put("transcript_confirmation_id",null);var f=assertThrows(TranscriptContracts.Failure.class,()->JdbcMinutesGenerationPreparation.writable(r,7));assertEquals(422,f.status());assertEquals("TRANSCRIPT_CONFIRMATION_REQUIRED",f.code());}
 @Test void readonlyOrUnresolvedMaterialAndFinalStatesDoNotBecomeTemplateInitializationCandidates(){for(var state:Map.<String,Object>of("ever_published",1L,"lifecycle","DELETING","governance_state","REVOKED","stage","PUBLISHED","material_snapshot_id",id,"final_confirmation_id",id,"materials_pending",1L).entrySet()){var r=root();r.put(state.getKey(),state.getValue());assertEquals(MinutesContracts.FailureCode.CAPABILITY_UNAVAILABLE,assertThrows(MinutesContracts.Failure.class,()->JdbcMinutesGenerationPreparation.writable(r,7)).code());}}
 @Test void incompleteSettingsPairIsUnavailableAndCannotBeOverwrittenByInitialization(){for(String key:List.of("template_revision_id","exclusion_revision_id")){var r=root();r.put(key,id);assertEquals(MinutesContracts.FailureCode.CAPABILITY_UNAVAILABLE,assertThrows(MinutesContracts.Failure.class,()->JdbcMinutesGenerationPreparation.writable(r,7)).code());}}
 @Test void exactRevisionAndCompleteExistingSettingsKeepTheirOriginalGuards(){var r=root();r.put("template_revision_id",id);r.put("exclusion_revision_id",id);assertDoesNotThrow(()->JdbcMinutesGenerationPreparation.writable(r,7));assertEquals("REVISION_CONFLICT",assertThrows(TranscriptContracts.Failure.class,()->JdbcMinutesGenerationPreparation.writable(r,6)).code());}
}
